import { ArrowRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import BlogLayout from '../components/BlogLayout';
import ArticleCard from '../components/ArticleCard';
import DisplayFrame from '../components/DisplayFrame';
import { useLocalizedPath } from '../i18n/paths';
import { guides } from '../content';

export default function GuidesIndex() {
  const { t, i18n } = useTranslation('edb');
  const localize = useLocalizedPath();
  const localizedGuides = guides(i18n.language);
  const [hub, ...rest] = localizedGuides;

  return (
    <BlogLayout
      title={t('guidesIndex.title')}
      description={t('guidesIndex.description')}
      readTime={null}
      section="guides"
      isIndex
      wide
      jsonLd={{
        '@context': 'https://schema.org',
        '@type': 'ItemList',
        name: t('guidesIndex.title'),
        itemListElement: localizedGuides.map((g, i) => ({
          '@type': 'ListItem',
          position: i + 1,
          url: `https://externaldisplayiphone.com${localize(g.path)}`,
          name: g.title,
        })),
      }}
    >
      {hub && (
        <a
          href={localize(hub.path)}
          className="group grid md:grid-cols-2 gap-0 overflow-hidden rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 hover:border-sky-400 dark:hover:border-sky-500 hover:shadow-xl transition-all duration-200 mb-8"
        >
          {hub.card && (
            hub.cardFullscreen ? (
              <div className="flex items-center justify-center p-6 bg-slate-100 dark:bg-slate-900">
                <DisplayFrame>
                  <img src={hub.card} alt="" width={hub.cardWidth || undefined} height={hub.cardHeight || undefined} loading="eager" decoding="async" className="absolute inset-0 w-full h-full object-cover" />
                </DisplayFrame>
              </div>
            ) : (
              <div className="relative aspect-[16/9] md:aspect-auto md:min-h-[240px] overflow-hidden bg-slate-100 dark:bg-slate-900">
                <img
                  src={hub.card}
                  alt=""
                  width={hub.cardWidth || undefined}
                  height={hub.cardHeight || undefined}
                  loading="eager"
                  decoding="async"
                  className="absolute inset-0 w-full h-full object-cover transition-transform duration-500 group-hover:scale-[1.03]"
                />
              </div>
            )
          )}
          <div className="p-6 flex flex-col justify-center">
            <div className="flex items-center gap-2 mb-3 flex-wrap">
              <span className="text-[11px] font-semibold px-2.5 py-0.5 rounded-full bg-sky-100 dark:bg-sky-900/40 text-sky-700 dark:text-sky-300">{hub.tag}</span>
              <span className="text-[11px] text-slate-500 dark:text-slate-400">{hub.readTime}</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-bold text-slate-900 dark:text-white leading-snug mb-2 group-hover:text-sky-600 dark:group-hover:text-sky-400 transition-colors">
              {hub.title}
            </h2>
            <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed">{hub.description}</p>
            <span className="inline-flex items-center gap-1 text-sm font-semibold text-sky-700 dark:text-sky-300 mt-4">
              {t('guidesIndex.startHere')} <ArrowRight className="w-4 h-4" />
            </span>
          </div>
        </a>
      )}

      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5">
        {rest.map((g) => <ArticleCard key={g.slug} article={g} />)}
      </div>

      <div className="mt-10 text-center">
        <a href={localize('/blog')} className="inline-flex items-center gap-1.5 text-sky-700 dark:text-sky-300 text-sm font-semibold hover:underline">
          {t('blogIndex.readBlogToo')} <ArrowRight className="w-4 h-4" />
        </a>
      </div>
    </BlogLayout>
  );
}
