import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

import enCommon from './locales/en/common.json';
import enHome from './locales/en/home.json';
import enFaq from './locales/en/faq.json';
import enBlog from './locales/en/blog.json';
import enLegal from './locales/en/legal.json';
import enInApp from './locales/en/inapp.json';

import roCommon from './locales/ro/common.json';
import roHome from './locales/ro/home.json';
import roFaq from './locales/ro/faq.json';
import roBlog from './locales/ro/blog.json';
import roLegal from './locales/ro/legal.json';
import roInApp from './locales/ro/inapp.json';

// Every locale is the same handful of per-page files, merged into one `edb`
// namespace so t('faq.q1.question') etc. keeps working regardless of which
// file a key actually lives in. Both locales are bundled statically (no
// dynamic import) on purpose: with only two locales this keeps prerendering
// deterministic, there's no lazy-chunk race for puppeteer to wait out.
const merge = (...parts) => Object.assign({}, ...parts);

export const rtlLanguages = ['ar', 'he'];
export const supportedLanguages = ['en', 'ro'];
export const defaultLanguage = 'en';
export const LANGUAGE_STORAGE_KEY = 'edb-language';
export const changeLanguage = (lng) => i18n.changeLanguage(lng);

export const initializeI18nSync = (initialLanguage = 'en') => {
  i18n
    .use(initReactI18next)
    .init({
      resources: {
        en: { edb: merge(enCommon, enHome, enFaq, enBlog, enLegal, enInApp) },
        ro: { edb: merge(roCommon, roHome, roFaq, roBlog, roLegal, roInApp) },
      },
      lng: initialLanguage,
      fallbackLng: defaultLanguage,
      supportedLngs: supportedLanguages,
      ns: ['edb'],
      defaultNS: 'edb',
      interpolation: {
        escapeValue: false
      },
      react: {
        useSuspense: false
      }
    });

  return i18n;
};

export default i18n;
