import { ArrowRight } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import ArticleCard from './ArticleCard';
import { useLocalizedPath } from '../i18n/paths';
import { guides, posts } from '../content';

/**
 * Home-page teaser for the content pack: the three most useful guides and the
 * three lead articles. Both lists come from src/content/manifest.json, so a new
 * guide only has to be imported to show up here.
 */
export default function BlogSection() {
  const { t, i18n } = useTranslation('edb');
  const localize = useLocalizedPath();
  const topGuides = guides(i18n.language).slice(0, 3);
  const topPosts = posts(i18n.language).filter((p) => p.card).slice(0, 3);

  return (
    <section className="py-16 px-4 sm:px-6 lg:px-8 bg-slate-100 dark:bg-slate-800/60">
      <div className="max-w-6xl mx-auto flex flex-col gap-14">
        <div>
          <div className="flex items-end justify-between mb-8 gap-4 flex-wrap">
            <div>
              <p className="text-xs font-bold text-sky-700 dark:text-sky-300 uppercase tracking-widest mb-2">{t('blogIndex.guidesEyebrow')}</p>
              <h2 className="text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white">{t('header.guides')}</h2>
            </div>
            <a href={localize('/guides')} className="inline-flex items-center gap-1.5 text-sky-700 dark:text-sky-300 text-sm font-medium hover:underline flex-shrink-0">
              {t('articleChrome.allGuides')} <ArrowRight className="w-4 h-4" />
            </a>
          </div>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5">
            {topGuides.map((g) => <ArticleCard key={g.slug} article={g} />)}
          </div>
        </div>

        <div>
          <div className="flex items-end justify-between mb-8 gap-4 flex-wrap">
            <div>
              <p className="text-xs font-bold text-sky-700 dark:text-sky-300 uppercase tracking-widest mb-2">{t('blogSection.articlesEyebrow')}</p>
              <h2 className="text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white">{t('blogSection.articlesHeading')}</h2>
              <p className="text-slate-600 dark:text-slate-300 mt-1.5 text-sm">{t('blogSection.articlesDescription')}</p>
            </div>
            <a href={localize('/blog')} className="inline-flex items-center gap-1.5 text-sky-700 dark:text-sky-300 text-sm font-medium hover:underline flex-shrink-0">
              {t('articleChrome.allArticles')} <ArrowRight className="w-4 h-4" />
            </a>
          </div>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5">
            {topPosts.map((p) => <ArticleCard key={p.slug} article={p} />)}
          </div>
        </div>
      </div>
    </section>
  );
}
